  /* ─── Seed to Firebase ─── */
  async function seedMathematicsQuestionBank() {
    const db = window.vishnuFirebase?.enabled ? window.vishnuFirebase.db : null;
    if (!db) return;

    // Pehle se delete kiye gaye (Recycle Bin) questions ki ID list nikal lo,
    // taaki unhe seed dobara na kare — warna delete karne ke baad wapas aa jaate hain.
    let deletedIds = new Set();
    try {
      const [delSnap, exclSnap] = await Promise.all([
        db.collection("deletedQuestions").get(),
        db.collection("seedExclusions").get()
      ]);
      delSnap.docs.forEach(d => deletedIds.add(d.id));
      exclSnap.docs.forEach(d => deletedIds.add(d.id));
    } catch (e) {
      console.warn("Math seed: deleted/exclusion list nahi mil payi, sab seed ho jaayenge:", e);
    }

    const total = questions.length;
    const BATCH_SIZE = 400;
    let skipped = 0;

    for (let start = 0; start < total; start += BATCH_SIZE) {
      const chunk = questions.slice(start, start + BATCH_SIZE);
      const b = db.batch();

      chunk.forEach((q, i) => {
        const id = `math-ssc-${(start + i + 1).toString().padStart(4, "0")}`;
        if (deletedIds.has(id)) { skipped++; return; } // pehle delete ho chuka hai, skip karo
        const ref = db.collection("questionBank").doc(id);
        b.set(ref, {
          subject: "Mathematics",
          chapter: q.chapter,
          textHI:  q.textHI,
          textEN:  q.textEN || q.textHI || "",
          text:    q.textHI,
          optionsHI: q.optionsHI,
          optionsEN: q.optionsEN || q.optionsHI || [],
          options:   q.optionsHI,
          answer:    q.answer,
          explanationHI: q.explanationHI || "",
          explanationEN: q.explanationEN || q.explanationHI || "",
          explanation:   q.explanationHI || "",
          seeded: true,
          createdAt: firebase.firestore.FieldValue.serverTimestamp(),
          updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
      });

      await b.commit();
      console.log(`Math bank chunk seeded: ${start + chunk.length}/${total}`);
    }
    console.log(`✅ Mathematics: Seeding completed successfully! (${skipped} previously-deleted question(s) skipped)`);
  }


  window.seedMathematicsQuestionBank = seedMathematicsQuestionBank;
